DELIMITER $$

/*!50003 DROP TRIGGER*//*!50032 IF EXISTS */ /*!50003 `T003_trigger_afeter_insert` */$$

/*!50003 CREATE */ /*!50017 DEFINER = 'userCreateDefiner'@'%' */ /*!50003 TRIGGER `T003_trigger_afeter_insert` AFTER INSERT ON `t003` FOR EACH ROW BEGIN
    INSERT INTO D085 (D085_D024_Id,D085_C007_Id,D085_Data,D085_Mensagem) values (NEW.T003_D024_Id,NEW.T003_C007_Id_Vendedor_Interno,curdate(),concat('Orçamento ',NEW.T003_Id));
