/*!50003 DROP TRIGGER*//*!50032 IF EXISTS */ /*!50003 `T019_trigger_atualiza_saldo` */$$

/*!50003 CREATE */ /*!50017 DEFINER = 'userCreateDefiner'@'%' */ /*!50003 TRIGGER `T019_trigger_atualiza_saldo` BEFORE INSERT ON `t019` FOR EACH ROW BEGIN
  declare xSaldo decimal(14,2) default 0; 
  select ifnull(D007_Valor_Saldo,0) into xSaldo from D007 WHERE D007_Id=NEW.T019_D007_Id;
