/*!50003 DROP TRIGGER*//*!50032 IF EXISTS */ /*!50003 `T020_trigger_atualizar_extras` */$$

/*!50003 CREATE */ /*!50017 DEFINER = 'userCreateDefiner'@'%' */ /*!50003 TRIGGER `T020_trigger_atualizar_extras` AFTER INSERT ON `t020` FOR EACH ROW BEGIN
  DECLARE xT020_Valor_Juros DECIMAL(19,2);
  DECLARE xT020_Valor_Desconto DECIMAL(19,2);
