/* Function  structure for function  `D016_Dolar` */

/*!50003 DROP FUNCTION IF EXISTS `D016_Dolar` */;
DELIMITER $$

/*!50003 CREATE DEFINER=`userCreateDefiner`@`%` FUNCTION `D016_Dolar`(xData date) RETURNS decimal(10,4)
BEGIN
    DECLARE xD016_Valor_Dolar DECIMAL(10,4);
    IF xData='0000-00-00'  THEN
          SELECT D016_Valor_Dolar INTO xD016_Valor_Dolar
            FROM D016
           WHERE D016_Valor_Dolar>0
        ORDER BY D016_Data desc
           LIMIT 0,1;
    ELSE
          SELECT D016_Valor_Dolar INTO xD016_Valor_Dolar
            FROM D016
           WHERE D016_Valor_Dolar>0
             AND D016_Data<=xData
        ORDER BY D016_Data desc
           LIMIT 0,1;
    END IF;
    IF xD016_Valor_Dolar IS NULL THEN
       SET xD016_Valor_Dolar = 0;
    END IF;
    RETURN xD016_Valor_Dolar;
END */$$
DELIMITER ;

/* Function  structure for function  `D017_Pesquisa_Substituicao` */

/*!50003 DROP FUNCTION IF EXISTS `D017_Pesquisa_Substituicao` */;
DELIMITER $$

/*!50003 CREATE DEFINER=`userCreateDefiner`@`%` FUNCTION `D017_Pesquisa_Substituicao`(xCodigo VARCHAR(25)) RETURNS varchar(25) CHARSET latin1
BEGIN
    DECLARE xCodigo_Produto VARCHAR(25);
    IF (xCodigo!='') THEN
       SELECT D001_Codigo_Produto INTO xCodigo_Produto FROM D001 WHERE D001_Codigo_Produto=xCodigo limit 1;
       IF xCodigo_Produto IS NULL THEN
          SELECT D001_Codigo_Produto INTO xCodigo_Produto FROM D001 WHERE REPLACE(REPLACE(REPLACE(D001_Codigo_Produto,'-',''),' ',''),'.','')=REPLACE(REPLACE(REPLACE(xCodigo,'-',''),' ',''),'.','') limit 1;
          IF xCodigo_Produto IS NULL THEN
             SELECT D001_Codigo_Produto INTO xCodigo_Produto FROM D017 LEFT JOIN D001 on D001_Id=D017_D001_Id WHERE REPLACE(REPLACE(REPLACE(D017_Codigo_Antigo,'-',''),' ',''),'.','')=REPLACE(REPLACE(REPLACE(xCodigo,'-',''),' ',''),'.','') order by D017_Data_Inclusao desc limit 1;
             IF xCodigo_Produto IS NULL THEN
                SELECT D001_Codigo_Produto INTO xCodigo_Produto
                  FROM D049
                 LEFT JOIN D001 ON D049_D001_Id=D001_Id
                 WHERE REPLACE(REPLACE(REPLACE(D049_Codigo_Produto_Fornecedor,'-',''),' ',''),'.','')=REPLACE(REPLACE(REPLACE(xCodigo,'-',''),' ',''),'.','') limit 1;
             END IF;
          END IF;
       END IF;
    END IF;
    RETURN xCodigo_Produto;
END */$$
DELIMITER ;

/* Function  structure for function  `D024_CFOP` */

/*!50003 DROP FUNCTION IF EXISTS `D024_CFOP` */;
DELIMITER $$

/*!50003 CREATE DEFINER=`userCreateDefiner`@`%` FUNCTION `D024_CFOP`(Cliente int, xD018_Id int, Empresa int) RETURNS int(3)
begin
  declare UF_Cliente varchar(2);
  declare Empresa_Grupo varchar(1);
  declare UF_Empresa varchar(2);
  declare xC004_CFOP_Venda_Dentro_Estado int(3);
  declare xC004_CFOP_Venda_Fora_Estado int(3);
  declare xD024_D006_Id int(10);
  select D018_UF,
         D024_Flag_Mono,
         D024_D006_Id
    into UF_Cliente,
         Empresa_Grupo,
         xD024_D006_Id
    from D024
    left join D018 on D018_Id=D024_D018_Id
   where D024_Id=Cliente
      or D018_Id=xD018_Id
   limit 1;
  select C004_Uf,
         C004_CFOP_Venda_Dentro_Estado,
         C004_CFOP_Venda_Fora_Estado
    into UF_Empresa,
         xC004_CFOP_Venda_Dentro_Estado,
         xC004_CFOP_Venda_Fora_Estado
    from C004 where C004_Id=Empresa;
  if UF_Cliente is null or UF_Empresa is null then
     return 0;
  end if;
  if xD024_D006_Id>0 then
     return xD024_D006_Id;
  end if;
  if Empresa_Grupo=1 then
     if UF_Cliente!=UF_Empresa then
        return 67;
     else
        return 66;
     end if;
  else
     if UF_Cliente!=UF_Empresa then
        return xC004_CFOP_Venda_Fora_Estado;
     else
        return xC004_CFOP_Venda_Dentro_Estado;
     end if;
  end if;
end */$$
DELIMITER ;

/* Function  structure for function  `ICMS_Inter_Estadual` */

/*!50003 DROP FUNCTION IF EXISTS `ICMS_Inter_Estadual` */;
DELIMITER $$

/*!50003 CREATE DEFINER=`userCreateDefiner`@`%` FUNCTION `ICMS_Inter_Estadual`(xC004_Id int(11), xD024_Id int(11), xD018_Id int(11), xFlag_Revenda_Consumidor varchar(1), xDocumento int(1), xTipo int(1)) RETURNS decimal(10,2)
BEGIN
    DECLARE xAliquota_ICMS DECIMAL(10,2);
    DECLARE xPercentual_Reducao_ICMS DECIMAL(10,4);
    DECLARE xC004_UF varchar(2);
    DECLARE xD024_Inscricao_Estadual VARCHAR(20);
    DECLARE xD024_Flag_Pessoa_Fisica_Juridica CHAR(1);
    DECLARE xD024_Flag_Revenda_Consumidor VARCHAR(1);
    DECLARE xD018_UF VARCHAR(2);
    DECLARE xD018_Aliquota_ICMS_1 DECIMAL(5,2);
    DECLARE xD018_Percentual_Reducao_ICMS_1 DECIMAL(5,2);
    DECLARE xD018_Aliquota_ICMS_2 DECIMAL(5,2);
    DECLARE xD018_Percentual_Reducao_ICMS_2 DECIMAL(5,2);
    SET xAliquota_ICMS=0;
    SET xPercentual_Reducao_ICMS=0;
    SET xD024_Inscricao_Estadual='';
    SET xD024_Flag_Pessoa_Fisica_Juridica='';
    SELECT C004_Uf
      INTO xC004_UF
      FROM C004
     WHERE C004_Id=xC004_Id;
     IF xD024_Id>0 THEN
        SELECT D024_Inscricao_Estadual,
              D024_Flag_Pessoa_Fisica_Juridica,
              D024_Flag_Revenda_Consumidor,
              D018_Id
         INTO xD024_Inscricao_Estadual,
              xD024_Flag_Pessoa_Fisica_Juridica,
              xD024_Flag_Revenda_Consumidor,
              xD018_Id
              FROM D024
              LEFT JOIN D018 ON D018_Id=D024_D018_Id
              WHERE D024_Id=xD024_Id limit 1;
    END IF;
    IF xD018_Id>0 THEN
        SET xD024_Flag_Revenda_Consumidor=xFlag_Revenda_Consumidor;
        SELECT D053_Aliquota_ICMS_1,
              D053_Percentual_Reducao_ICMS_1,
              D053_Aliquota_ICMS_2,
              D053_Percentual_Reducao_ICMS_2,
              D018_UF
          INTO xD018_Aliquota_ICMS_1,
              xD018_Percentual_Reducao_ICMS_1,
              xD018_Aliquota_ICMS_2,
              xD018_Percentual_Reducao_ICMS_2,
              xD018_UF
              FROM D018
              LEFT JOIN D053 on D053_D018_Id=D018_Id and D053_C004_Id=xC004_Id
              WHERE D018_Id=xD018_Id
              LIMIT 1;
    END IF;
    IF xD024_Id<=0 AND xD024_Flag_Revenda_Consumidor='R' THEN
       SET xAliquota_ICMS=xD018_Aliquota_ICMS_2;
       SET xPercentual_Reducao_ICMS=xD018_Percentual_Reducao_ICMS_1;
    ELSEIF xD024_Id<=0 AND xD024_Flag_Revenda_Consumidor='C' THEN
       SET xAliquota_ICMS=xD018_Aliquota_ICMS_1;
       SET xPercentual_Reducao_ICMS=xD018_Percentual_Reducao_ICMS_2;
    ELSEIF xD024_Inscricao_Estadual='' OR xD024_Inscricao_Estadual='ISENTO' OR  xD024_Flag_Pessoa_Fisica_Juridica='F' THEN
       SET xAliquota_ICMS=xD018_Aliquota_ICMS_1;
       SET xPercentual_Reducao_ICMS=xD018_Percentual_Reducao_ICMS_2;
    ELSEIF (xD024_Inscricao_Estadual!='' AND xD024_Inscricao_Estadual!='ISENTO') OR  xD024_Flag_Pessoa_Fisica_Juridica='J' THEN
       SET xAliquota_ICMS=xD018_Aliquota_ICMS_2;
       SET xPercentual_Reducao_ICMS=xD018_Percentual_Reducao_ICMS_1;
    END IF;
    IF xC004_UF='PR' and xD018_UF='PR' and xD024_Flag_Revenda_Consumidor='R' THEN
       SET xAliquota_ICMS=12;
    END IF;

    IF xTipo=1 THEN
       RETURN xAliquota_ICMS;
    ELSEIF xTipo=2 THEN
       RETURN xPercentual_Reducao_ICMS;
    END IF;

END */$$
DELIMITER ;

/* Function  structure for function  `Quantidade` */

/*!50003 DROP FUNCTION IF EXISTS `Quantidade` */;
DELIMITER $$

/*!50003 CREATE DEFINER=`userCreateDefiner`@`%` FUNCTION `Quantidade`(xQuantidade decimal(10,3), xUnidade varchar(3), xPeso_Unitario decimal(10,3), xPeso_Pacote decimal(10,3), xQuantidade_Pacote int(10), xUnidade_Retorno varchar(3)) RETURNS decimal(10,3)
BEGIN
   declare xQte_KLG decimal(10,3);
   declare xQte_PCT decimal(10,3);
   declare xQte_UND decimal(10,3);
   if xUnidade='KLG' THEN
       set xQte_KLG = xQuantidade;
       set xQte_PCT = xQuantidade/xPeso_Pacote;
       set xQte_UND = xQuantidade/xPeso_Unitario;
   elseif xUnidade='PCT' THEN
       set xQte_KLG = xQuantidade*xPeso_Pacote;
       set xQte_PCT = xQuantidade;
       set xQte_UND = xQuantidade*xQuantidade_Pacote;
   elseif xUnidade='UND' THEN
       set xQte_KLG = xQuantidade*xPeso_Unitario;
       set xQte_PCT = xQuantidade/xQuantidade_Pacote;
       set xQte_UND = xQuantidade;
   end if;
   if xUnidade_Retorno='KLG' THEN
      return xQte_KLG;
   elseif xUnidade_Retorno='PCT' THEN
      return xQte_PCT;
   elseif xUnidade_Retorno='UND' THEN
      return xQte_UND;
   end if;
END */$$
DELIMITER ;

/* Function  structure for function  `T003_IPV_Medio` */

/*!50003 DROP FUNCTION IF EXISTS `T003_IPV_Medio` */;
DELIMITER $$

/*!50003 CREATE DEFINER=`userCreateDefiner`@`%` FUNCTION `T003_IPV_Medio`(xT003_Id int(11),xTipo int(1)) RETURNS decimal(10,4)
BEGIN
    DECLARE xTotal_IPV DECIMAL(10,4);
    DECLARE xTotal_Itens INT(10);
    DECLARE xIPV_Medio DECIMAL(10,4);
    IF xTipo=1 THEN
       SELECT SUM(T004_Valor_Total_Preco)/SUM(T004_Valor_Total_Custo),
              SUM(1)
         INTO xTotal_IPV,
              xTotal_Itens
         FROM T004
    LEFT JOIN T003 on T003_Id=T004_T003_Id
    LEFT JOIN D009 on D009_Id=T004_D009_Id
        WHERE T004_T003_Id=xT003_Id
          AND T004_Quantidade>0
          AND T004_Flag_Cancelado!='S'
          AND ifnull(D009_Flag_Preco_Tabelado,'N')!='S'
        GROUP BY T004_T003_Id;
    ELSEIF xTipo=2 THEN
       SELECT SUM(T004_Valor_Total_Preco_Confirmado)/SUM(T004_Valor_Total_Custo_Confirmado),
              SUM(1)
         INTO xTotal_IPV,
              xTotal_Itens
         FROM T004
    LEFT JOIN T003 on T003_Id=T004_T003_Id
    LEFT JOIN D009 on D009_Id=T004_D009_Id
        WHERE T004_T003_Id=xT003_Id
          AND T004_Quantidade_Confirmada>0
          AND T004_Flag_Cancelado!='S'
          AND ifnull(D009_Flag_Preco_Tabelado,'N')!='S'
        GROUP BY T004_T003_Id;
    ELSEIF xTipo=3 THEN
       SELECT SUM(T004_Valor_Total_Preco)/SUM(T004_Valor_Total_Custo),
              SUM(1)
         INTO xTotal_IPV,
              xTotal_Itens
         FROM T004
    LEFT JOIN T003 on T003_Id=T004_T003_Id
    LEFT JOIN D009 on D009_Id=T004_D009_Id
        WHERE T004_T003_Id=xT003_Id
          AND T004_Quantidade>0
          AND T004_Flag_Cancelado!='S'
          AND ifnull(D009_Flag_Preco_Tabelado,'N')!='S'
        GROUP BY T004_T003_Id;
    ELSEIF xTipo=4 THEN
       SELECT SUM(T004_Valor_Total_Preco_Confirmado)/SUM(T004_Valor_Total_Custo_Confirmado),
              SUM(1)
         INTO xTotal_IPV,
              xTotal_Itens
         FROM T004
    LEFT JOIN T003 on T003_Id=T004_T003_Id
    LEFT JOIN D009 on D009_Id=T004_D009_Id
        WHERE T004_T003_Id=xT003_Id
          AND T004_Quantidade_Confirmada>0
          AND T004_Flag_Cancelado!='S'
          AND ifnull(D009_Flag_Preco_Tabelado,'N')!='S'
        GROUP BY T004_T003_Id;
    END IF;
    IF xTotal_Itens>0 THEN
       SET xIPV_Medio=xTotal_IPV;
    ELSE
       SET xIPV_Medio=0;
    END IF;
    RETURN xIPV_Medio;
END */$$
DELIMITER ;

/* Function  structure for function  `T003_Prazos` */

/*!50003 DROP FUNCTION IF EXISTS `T003_Prazos` */;
DELIMITER $$

/*!50003 CREATE DEFINER=`userCreateDefiner`@`%` FUNCTION `T003_Prazos`(xT003_Id int(11)) RETURNS varchar(255) CHARSET latin1
BEGIN
    DECLARE xTotal_Parcelas INT(2) DEFAULT 0;
    DECLARE xTotal_Prazos VARCHAR(255);
    DECLARE xRetorno VARCHAR(255) DEFAULT '';
    DECLARE xPrazos_Dias INT(5) DEFAULT 0;
    DECLARE xNumero_Parcela  INT(3) DEFAULT 0;
    DECLARE xFlag_ACP VARCHAR(1) DEFAULT ' ';
    DECLARE xFlag_Gera_Contas VARCHAR(1) DEFAULT ' ';

    SELECT T003_Flag_ACP,
           D006_Flag_Gera_Contas
      INTO xFlag_ACP,
           xFlag_Gera_Contas
      FROM T003
      LEFT JOIN D006 ON D006_Id=T003_D006_Id
     WHERE T003_Id=xT003_Id;
    IF xFlag_ACP!=2 AND xFlag_Gera_Contas!='N' THEN

       SELECT SUM(1),
              CONCAT(GROUP_CONCAT(T089_Prazos_Dias SEPARATOR ' / '),' Dias'),
              T089_Prazos_Dias,
              T089_Numero_Parcela
         INTO xTotal_Parcelas,
