/* Function  structure for function  `T054_Status_Importacao` */

/*!50003 DROP FUNCTION IF EXISTS `T054_Status_Importacao` */;
DELIMITER $$

/*!50003 CREATE DEFINER=`userCreateDefiner`@`%` FUNCTION `T054_Status_Importacao`(xStatus int(2),xTipo int(1)) RETURNS varchar(25) CHARSET latin1
BEGIN
    DECLARE xDescricao VARCHAR(25);
    IF xTipo=1 THEN
       IF xStatus=1 THEN
          SET xDescricao = 'Imprimir Pedido';
       END IF;
       IF xStatus=2 THEN
          SET xDescricao = 'Conferindo Pe?as';
       END IF;
       IF xStatus=3 THEN
          SET xDescricao = 'Emitindo Nota Fiscal';
       END IF;
       IF xStatus=4 THEN
          SET xDescricao = 'Finalizado';
       END IF;
    END IF;
    IF xTipo=2 THEN
       IF xStatus=1 THEN
          SET xDescricao = 'Imprima o Pedido';
       END IF;
       IF xStatus=2 THEN
          SET xDescricao = 'Confira a Mercadoria';
       END IF;
       IF xStatus=3 THEN
          SET xDescricao = 'Emitir Nota Fiscal';
       END IF;
       IF xStatus=4 THEN
          SET xDescricao = 'Finalizado';
       END IF;
    END IF;
    RETURN xDescricao;
END */$$
DELIMITER ;

/* Function  structure for function  `T055_Converte_Custo` */

/*!50003 DROP FUNCTION IF EXISTS `T055_Converte_Custo` */;
DELIMITER $$

/*!50003 CREATE DEFINER=`userCreateDefiner`@`%` FUNCTION `T055_Converte_Custo`(xT054_Id INT(10),xT052_D044_Id INT(10),xT053_Valor_Custo_Unitario DECIMAL(10,2)) RETURNS decimal(19,5)
BEGIN
    DECLARE xT054_Valor_Cambio_Dolar DECIMAL(10,4);
    DECLARE xT054_Valor_Cambio_Euro  DECIMAL(10,4);
    DECLARE xT054_D044_Id INTEGER;
    DECLARE xValor_Custo DECIMAL(19,5);
    DECLARE xValor_Custo_Real DECIMAL(19,5);
    SELECT T054_Valor_Cambio_Dolar,
           T054_Valor_Cambio_Euro,
           T054_D044_Id
      INTO
           xT054_Valor_Cambio_Dolar,
           xT054_Valor_Cambio_Euro,
           xT054_D044_Id
      FROM T054
       WHERE T054_Id=xT054_Id;
    IF xT052_D044_Id=xT054_D044_Id THEN
        SET xValor_Custo = xT053_Valor_Custo_Unitario;
    ELSE
        IF xT054_D044_Id=2 AND xT052_D044_Id=3 THEN
           SET xValor_Custo_Real = xT053_Valor_Custo_Unitario * xT054_Valor_Cambio_Euro;
           SET xValor_Custo = xValor_Custo_Real / xT054_Valor_Cambio_Dolar;
        END IF;
        IF xT054_D044_Id=3 AND xT052_D044_Id=2 THEN
           SET xValor_Custo_Real = xT053_Valor_Custo_Unitario * xT054_Valor_Cambio_Dolar;
           SET xValor_Custo = xValor_Custo_Real / xT054_Valor_Cambio_Euro;
        END IF;
    END IF;
    RETURN xValor_Custo;
END */$$
DELIMITER ;

/* Function  structure for function  `T066_Quantidade_Liquido` */

/*!50003 DROP FUNCTION IF EXISTS `T066_Quantidade_Liquido` */;
DELIMITER $$

/*!50003 CREATE DEFINER=`userCreateDefiner`@`%` FUNCTION `T066_Quantidade_Liquido`(xT066_Id INT(11)) RETURNS decimal(20,5)
BEGIN
     DECLARE xT185_Qtd_Para_Separar DECIMAL(20,5);
     
     SELECT SUM(T185_Qtd_Para_Separar) INTO xT185_Qtd_Para_Separar FROM T185 
			LEFT JOIN T006 ON T006_Id=T185_T006_Id
			LEFT JOIN T005 ON T005_Id=T006_T005_Id 
			WHERE 
				T185_T066_Id=xT066_Id
				AND T006_Flag_Status!='3'
				AND T005_Flag_Status!='9'
				AND T005_Flag_Status!='5'
				AND T005_Flag_Status!='7'
				AND T005_Flag_Status!='11'
				AND T005_Flag_Status!='8';
   IF xT185_Qtd_Para_Separar IS NULL THEN
     SET xT185_Qtd_Para_Separar = 0;
   END IF;
   RETURN xT185_Qtd_Para_Separar;
END */$$
DELIMITER ;

