/* Function  structure for function  `T129_Quantidade_Falta_Lancar` */

/*!50003 DROP FUNCTION IF EXISTS `T129_Quantidade_Falta_Lancar` */;
DELIMITER $$

/*!50003 CREATE DEFINER=`userCreateDefiner`@`%` FUNCTION `T129_Quantidade_Falta_Lancar`(xT129_Id INT(11),xT130_Id INT(11)) RETURNS decimal(10,3)
BEGIN
     DECLARE xQuantidade_Falta_Lancar DECIMAL(10,3);
     SELECT IFNULL(T129_Quantidade_Separacao,0)-IFNULL(SUM(T014_Quantidade),0)-IFNULL(SUM(T130_Quantidade),0)
       INTO xQuantidade_Falta_Lancar
       FROM T129
  LEFT JOIN T130 on T130_T129_Id=T129_Id and T130_Id!=xT130_Id
  LEFT JOIN T014 on T014_T129_Id=T129_Id
  LEFT JOIN T013 on T013_Id=T014_T013_Id
  LEFT JOIN T128 on T128_Id=T129_T128_Id
      WHERE T129_Id=xT129_Id
        AND T128_Flag_Cancelada!='S'
        AND T129_Flag_Cancelada!='S'
        AND T013_Flag_Cancelada!='S';
     IF xQuantidade_Falta_Lancar IS NULL or xQuantidade_Falta_Lancar<0 THEN
        SET xQuantidade_Falta_Lancar = 0;
     END IF;
     RETURN xQuantidade_Falta_Lancar;
END */$$
DELIMITER ;

