DELIMITER $$

/*!50003 CREATE DEFINER=`userCreateDefiner`@`%` PROCEDURE `T002_Gravar_Totalizacao`(xT002_Id int(11))
BEGIN
     UPDATE T002
        SET T002_Valor_Comissao=T002_Valor_Base_Comissao*(T002_Percentual_Comissao/100),
